--
-- Name: medical_report_webhooks; Type: VIEW; Schema: public; Owner: pal
--

CREATE VIEW public.medical_report_webhooks AS
 SELECT id,
    "timestamp",
    (payload ->> 'patient_name'::text) AS patient_name,
    (payload ->> 'patient_age'::text) AS patient_age,
    (payload ->> 'patient_gender'::text) AS patient_gender,
    (payload -> 'lab_reports'::text) AS lab_reports,
    (payload -> 'invoices'::text) AS invoices,
    processed,
    patient_id,
    created_at
   FROM public.webhook_events
  WHERE (((event_type)::text = 'medical_report'::text) OR (payload ? 'lab_reports'::text));


ALTER VIEW public.medical_report_webhooks OWNER TO pal;

